checkitem.compliant:
( ( COMPONENT = 'UIS4HOP1' and VERSION = '800' and not( (lpad(SP,4,'0')) < '0005' ) )
or ( COMPONENT = 'UIS4HOP1' and VERSION = '900' and not( (lpad(SP,4,'0')) < '0002' ) )
)

checkitem.noncompliant:
( ( COMPONENT = 'UIS4HOP1' and VERSION = '800' and (lpad(SP,4,'0')) < '0005' )
or ( COMPONENT = 'UIS4HOP1' and VERSION = '900' and (lpad(SP,4,'0')) < '0002' )
)

( ( COMPONENT = 'UIS4HOP1' and VERSION = '800' and lpad(SP,4,'0') between '0001' and '0004' )
or ( COMPONENT = 'UIS4HOP1' and VERSION = '900' and lpad(SP,4,'0') between '0000' and '0001' )
)
